def get_connected_components(grid):
    """Get connected components by color using 8-connectivity."""
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    def get_comp(r, c):
        comp = []
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            comp.append((cr, cc))
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
        return sorted(comp)

    comps_by_color = {}
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != 0 and not visited[r][c]:
                pixels = get_comp(r, c)
                if color not in comps_by_color:
                    comps_by_color[color] = []
                comps_by_color[color].append(pixels)

    # Flatten all components
    all_comps = []
    for color, comp_list in comps_by_color.items():
        for pixels in comp_list:
            all_comps.append({'color': color, 'pixels': pixels, 'area': len(pixels)})

    return all_comps

